use biome_console::markup;
use biome_diagnostics::Severity;
use biome_js_syntax::jsx_ext::AnyJsxElement;
use biome_rowan::AstNode;
use biome_rule_options::use_iframe_sandbox::UseIframeSandboxOptions;

declare_lint_rule! {
    /// Enforces the usage of the attribute `sandbox` for the element `iframe`.
    ///
    /// The `sandbox` attribute enables an extra set of restrictions for the content in the iframe,
    /// protecting against malicious scripts and other security threats. Without it, the embedded
    /// document runs with the same privileges as the parent page.
    ///
    /// ## Examples
    ///
    /// ### Invalid
    ///
    /// ```jsx,expect_diagnostic
    /// <iframe />
    /// ```
    ///
    /// ```jsx,expect_diagnostic
    /// <iframe sandbox />
    /// ```
    ///
    /// ### Valid
    ///
    /// ```jsx
    /// <>
    ///   <iframe sandbox="" />
    ///   <iframe sandbox="allow-scripts" />
    ///   <iframe {...props} />
    /// </>
    /// ```
    ///
    /// ## Resources
    ///
    /// - [MDN: iframe sandbox attribute](https://developer.mozilla.org/en-US/docs/Web/HTML/Element/iframe#sandbox)
    ///
    pub UseIframeSandbox {
        version: "next",
        name: "useIframeSandbox",
        language: "jsx",
        sources: &[RuleSource::EslintReact("iframe-missing-sandbox").same()],
        recommended: false,
        severity: Severity::Error,
    }
}

impl Rule for UseIframeSandbox {
    type Query = Ast<AnyJsxElement>;
    type State = ();
    type Signals = Option<Self::State>;
    type Options = UseIframeSandboxOptions;

    fn run(ctx: &RuleContext<Self>) -> Self::Signals {
        let element = ctx.query();
        let name = element.name().ok()?.name_value_token().ok()?;

        if name.text_trimmed() == "iframe" {
            if let Some(sandbox_attribute) = element.find_attribute_by_name("sandbox") {
                // The attribute is present. Only flag it when it doesn't carry a
                // string value (i.e. a boolean attribute like `<iframe sandbox />`),
                // unless a spread prop after it could provide the value.
                let has_string_value = sandbox_attribute
                    .as_static_value()
                    .is_some_and(|value| value.as_string_constant().is_some());

                if !has_string_value && !element.has_trailing_spread_prop(&sandbox_attribute) {
                    return Some(());
                }
            } else if !element.has_spread_prop() {
                return Some(());
            }
        }

        None
    }

    fn diagnostic(ctx: &RuleContext<Self>, _state: &Self::State) -> Option<RuleDiagnostic> {
        let node = ctx.query();
        Some(
            RuleDiagnostic::new(
                rule_category!(),
                node.syntax().text_trimmed_range(),
                markup! {
                    "Iframe doesn't have the sandbox attribute."
                },
            )
            .note(markup! {
                "The sandbox attribute enables an extra set of restrictions for the content in the iframe, protecting against malicious scripts and other security threats."
            })
            .note(markup! {
                "Provide a sandbox attribute when using iframe elements."
            }),
        )
    }
}
